Un árbol de directorios lista los nombres de una carpeta: primero las subcarpetas de la izquierda, luego el nombre de la carpeta y luego las de la derecha.

function listarCarpetas(carpeta) {
  const nombres = [];
  function visitar(c) {
    if (c === null) return;
    visitar(c.izquierda);
    nombres.push(c.nombre);
    visitar(c.derecha);
  }
  visitar(carpeta);
  return nombres;
}
